package com.rapidresolve;
import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import org.mindrot.jbcrypt.BCrypt;
@WebServlet("/register") public class RegisterServlet extends HttpServlet { protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String n=r.getParameter("name"),e=r.getParameter("email"),p=r.getParameter("password"); try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement("INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)")){q.setString(1,n);q.setString(2,e);q.setString(3,BCrypt.hashpw(p,BCrypt.gensalt(12)));q.setString(4,"user");q.executeUpdate();s.sendRedirect("login.html?success=registered");}catch(SQLException x){s.sendRedirect("register.html?error=exists");}}}
